cd /home/axel/LeanAlgebraicGeometry-Horizon && for id in I-0083 I-0319 I-0346 I-0354 I-0367 I-0372 I-0387 I-0397 I-0408 I-0430 I-0437 I-0481 I-0489 I-0491 issue-1 issue-2; do echo "=========== $id"; "$HORIZON_BIN" inbox show $id --no-mark-read --json 2>/dev/null | python3 -c "
import json,sys
try: d=json.load(sys.stdin)
except Exception as e:
    print('  UNREADABLE', e); raise SystemExit
it=d.get('item',d)
print(' kind',it.get('kind'),'| to',it.get('audience'),'| labels',it.get('labels'),'|',it.get('created_at','')[:16])
print((it.get('body') or '')[:600])
for c in (it.get('comments') or [])[-2:]: print('   >>>',(c.get('body') or '')[:250].replace('\n',' '))
"; done

cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 - <<'EOF'
import glob,re
for id in ['I-0083','I-0354','I-0367','I-0397','I-0408','I-0430','I-0437','I-0319','issue-1','issue-2','I-0492','I-0365']:
    for f in glob.glob(f'/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/inbox/**/items/{id}.yaml',recursive=True):
        txt=open(f).read()
        # print all top-level scalar-ish keys except body
        keep=[]
        for line in txt.splitlines():
            if re.match(r'^(labels|audience|owner|status|kind|scope|project|recipients|to):',line): keep.append(line.strip())
            elif re.match(r'^- ',line) and keep and keep[-1].startswith('labels'): keep.append('   '+line.strip())
        print(id, '|', '; '.join(keep))
EOF
